def solve(payload):
    from collections import defaultdict, deque
    window, threshold = payload["window_s"], payload["threshold"]
    if window <= 0 or threshold <= 0:
        return {"error": "invalid_policy"}
    failures = defaultdict(deque)
    alerts = []
    for event in payload["events"]:
        queue = failures[event["user"]]
        while queue and queue[0] <= event["time"] - window:
            queue.popleft()
        if event["outcome"] == "success":
            queue.clear()
            continue
        previous = len(queue)
        queue.append(event["time"])
        if previous < threshold <= len(queue):
            alerts.append({"user": event["user"], "time": event["time"], "count": len(queue)})
    return {"alerts": alerts}

